/* api.c: the engine's routines for the game (step 8.5d). The game (task 0) calls them through __engcall (engcall.asm); the
 * table api_tab (generated by tools/mkgame.py into build/game/api_tab.c) maps the numbers of build/game/engine_names.txt to
 * the api_<Name> functions of this file; a name without a function here stops the program with its number in result word 30
 * (api_unimpl: MB_RESULT(30) = number, status 2). Entry 0 is the bank loader, called by __farcall.
 *
 * The arguments are on the shared stack exactly as the game's C compiler pushed them, so every api_ function has the
 * parameter types of the routine it stands for (or of its wrapper in src/game/engapi.c, which copies strings and results
 * through its own frame: a pointer into the game's native memory would mean nothing in task 1).
 * A picture is a handle: 1..NPIC, an index into pics[]; the game keeps it in its picture variables as the low word of a
 * farptr (0 = no picture). The pixels stay in the engine's blocks (gfx.c). */
#include "eng.h"
#include "mailbox.h"
#include "gamemap.h"

extern u8 banktab[64];
void eng_halt(void);

/* ---- files into physical blocks */

static u8 sbuf[256];

/* A whole file from `drive` into physical blocks first_blk, +1, ... (8,192 bytes each); returns its size or 0. */
u32 eng_read_blocks(const char *name8, const char *ext3, u8 drive, u8 first_blk)
{
    RsFile f;
    u32 size, off;
    u16 n;
    u8 t;
    u8 rst = rs_open(&f, drive, name8, ext3);
    DBG(2, ((u16)drive << 8) | rst);
    if (rst != 0)
        return 0;
    size = (u32)(f.sectors - 1) * 256UL + f.last_bytes;
    for (off = 0; off < size; off += 256) {
        n = (u16)((size - off) < 256UL ? (size - off) : 256UL);
        for (t = 0; t < 5; t++) {
            rst = rs_read(&f, off, sbuf, n);
            if (rst == 0)
                break;
            DBG(3, rst);
        }
        if (rst != 0)
            return 0;
        win_set(0, (u8)(first_blk + (u8)(off >> 13)));
        k_copy(WIN0 + (u16)(off & 0x1FFFu), sbuf, 128);
        k_copy(WIN0 + (u16)(off & 0x1FFFu) + 128, sbuf + 128, 128);
    }
    return size;
}

/* ---- the code banks */

#define POOL_N ((BANK_POOL_END - BANK_POOL_FIRST) / 2)
static u8 pool_bank[POOL_N];              /* the bank in pool entry k, 0 = free */
u8 bank_drive[64];                        /* the drive a bank's file is on (BANKS.IDX, read at start-up) */
static u8 pool_next;

/* a bank is in use when it is mapped or a caller on the bank stack will come back to it (farcall.asm: 5 bytes an entry,
 * the first is the bank that was mapped before the call) */
static u8 bank_in_use(u8 bank)
{
    const u8 *p = *(u8 **)0x81;           /* FC_BSPTR */
    if (*(u8 *)0x80 == bank)              /* FC_CURBANK */
        return 1;
    for (; p < (const u8 *)0x2000; p += 5)
        if (*p == bank)
            return 1;
    return 0;
}

u16 api_bankload(u16 bank)
{
    char name[9];
    u8 k, t;
    u32 size;
    name[0] = 'B';
    name[1] = 'A';
    name[2] = 'N';
    name[3] = 'K';
    name[4] = (char)('0' + bank / 10);
    name[5] = (char)('0' + bank % 10);
    name[6] = ' ';
    name[7] = ' ';
    name[8] = 0;
    DBG(1, bank);
    for (t = 0; t < POOL_N; t++) {
        k = (u8)((pool_next + t) % POOL_N);
        if (pool_bank[k] == 0 || !bank_in_use(pool_bank[k]))
            break;
    }
    if (t == POOL_N) {                     /* every bank is on the stack: cannot happen with 12 and a call depth of 5 */
        MB_RESULT(31) = bank;
        MB_STATUS = MB_FAIL;
        eng_halt();
    }
    if (pool_bank[k])
        banktab[pool_bank[k] - 1] = 0;
    size = eng_read_blocks(name, "BIN", bank_drive[bank], (u8)(BANK_POOL_FIRST + 2 * k));
    if (size == 0) {
        MB_RESULT(31) = bank;
        MB_RESULT(29) = 1;                 /* the bank file is missing or unreadable */
        MB_STATUS = MB_FAIL;
        eng_halt();
    }
    MB_RESULT(7) = (u16)bank;
    MB_RESULT(8) = (u16)size;
    MB_RESULT(9) = (u16)(MB_RESULT(9) + 1);
    pool_bank[k] = (u8)bank;
    banktab[bank - 1] = (u8)(BANK_POOL_FIRST + 2 * k);
    pool_next = (u8)((k + 1) % POOL_N);
    return 0;
}

/* a routine of engine_names.txt that has no function here */
extern u8 eng_idx;
void api_unimpl(void)
{
    MB_RESULT(30) = eng_idx;
    MB_STATUS = MB_FAIL;
    eng_halt();
}

/* ---- pictures */

#define NPIC 48
#define H_DRAWBUF 0x7F01u                 /* DrawBuf, the staging buffer of gfx.c: not a Pic */
static Pic pics[NPIC];
static u8 pic_live[NPIC];

static u16 pic_new(void)
{
    u8 i;
    for (i = 0; i < NPIC; i++)
        if (!pic_live[i]) {
            pic_live[i] = 1;
            return (u16)(i + 1);
        }
    return 0;
}

static Pic *pic_of(u32 h)
{
    if (h == 0 || h > NPIC || !pic_live[(u8)h - 1])
        return 0;
    return &pics[(u8)h - 1];
}

/* The name of a picture file as a Pascal string -> 8 characters, upper case, space padded */
static void name8_of(const u8 *pas, char *out)
{
    u8 i, n = pas[0], c;
    for (i = 0; i < 8; i++) {
        c = i < n ? pas[1 + i] : ' ';
        if (c >= 'a' && c <= 'z')
            c = (u8)(c - 32);
        out[i] = (char)c;
    }
    out[8] = 0;
}

u16 api_LoadPicture(const u8 *name, u8 id, u8 flags, u8 color)
{
    char n8[9];
    DaxEntry e;
    Vol *v;
    u16 h;
    u8 st;
    name8_of(name, n8);
    st = vol_lookup(n8, id, &v, &e);
    DBG(6, ((u16)id << 4) | st);
    if (st != 0)
        return 0;
    h = pic_new();
    if (h == 0)
        return 0;
    st = pic_load_e(&pics[h - 1], &v->f, &e, color, (u8)(flags & 1));
    if (st != 0) {
        pic_live[h - 1] = 0;
        return 0;
    }
    return h;
}

u16 api_AllocatePicture(u16 height, u16 wcols, u8 items, u8 flags)
{
    u16 h;
    if (height == 0xA8 && wcols == 0x15)
        return H_DRAWBUF;
    h = pic_new();
    if (h == 0)
        return 0;
    if (pic_alloc(&pics[h - 1], (u8)height, (u8)wcols, items, (u8)(flags & 1)) != 0) {
        pic_live[h - 1] = 0;
        return 0;
    }
    return h;
}

void api_ReleasePicture(u16 h)
{
    Pic *p = pic_of(h);
    if (p) {
        pic_free(p);
        pic_live[h - 1] = 0;
    }
}

void api_ShowPicture(s16 col, s16 row, u32 buf)
{
    Pic *p = pic_of(buf);
    DBG(5, ((u16)(u8)col << 6) | ((u16)(u8)row << 1) | (p != 0));
    if (p && col >= 0 && row >= 0)
        gfx_item(p, 0, (u8)col, (u8)row);
}

void api_ShowPictureItem(s16 col, s16 row, u16 h, u8 item)
{
    Pic *p = pic_of(h);
    if (p && col >= 0 && row >= 0 && item < p->items)
        gfx_item(p, item, (u8)col, (u8)row);
}

void api_DrawPictureItem(s16 col, s16 row, u8 item, u8 flags, u32 src, u32 dst)
{
    Pic *p = pic_of(src);
    (void)dst;                             /* always DrawBuf */
    if (p && item < p->items)
        db_item(p, item, (u8)col, (u8)row, flags);
}

void api_FillPictureRect(s16 col, s16 row, u16 w, u16 h, u8 color, u32 palette, u32 target)
{
    (void)palette;
    (void)target;
    db_fill(col, row, w, h, color);
}

void api_FlushPictureChanges(void)
{
    db_flush();
}

/* RemapPictureColors (res07 0464:1F51): the colours of one item (FirstItem, item 0 when negative: the original's quirk) that
 * the map `from` names become the ones `to` names; the maps arrive copied to the wrapper's frame. Flicker (a random subset
 * of the pixels, doors only) needs the game's Random: not here yet. */
void api_RemapPictureColors(const u8 *from, const u8 *to, s16 first, u8 flicker, u16 h)
{
    u8 lut[16], c;
    Pic *p = pic_of(h);
    if (p == 0)
        return;
    if (flicker) {
        MB_RESULT(30) = 0xF1;
        MB_STATUS = MB_FAIL;
        eng_halt();
    }
    for (c = 0; c < 16; c++)
        lut[c] = c;
    for (c = 0; c < 16; c++)
        if (from[c] != to[c])
            lut[from[c] & 15] = (u8)(to[c] & 15);
    pic_remap(p, (u8)(first < 0 ? 0 : first), lut);
}

void api_SetPaletteRegister(u8 reg, u8 color)
{
    gfx_pal_reg(reg, color);
}

/* ---- DAX blocks and files: LoadDaxBlock and the Pascal file runtime of the game (src/game/engapi.c, rtl_sys.c) */

#define STAGE_BLK 0x0E                    /* two blocks: the unpacked block api_DaxLoad found */
static u16 stage_size;

/* The unpacked block `id` of the DAX file `name` (a Pascal string, no extension) into the stage; its size, 0 = not found */
u16 api_DaxLoad(const u8 *name, u16 id)
{
    char n8[9];
    DaxEntry e;
    Vol *v;
    u8 st;
    stage_size = 0;
    name8_of(name, n8);
    st = vol_lookup(n8, (u8)id, &v, &e);
    if (st != 0 && vol_mount(&vols[1], 1) == 0)          /* a new disk may have been put in the second drive */
        st = vol_lookup(n8, (u8)id, &v, &e);
    if (st != 0 || e.raw > 0x4000u)
        return 0;
    if (dax_unpack(&v->f, &e, 0, 0, STAGE_BLK, 0, 0) != 0)
        return 0;
    stage_size = e.raw;
    return stage_size;
}

/* n bytes (n <= 256) of the stage from `off` to dst (the caller's frame) */
void api_DaxRead(u16 off, u8 *dst, u16 n)
{
    u16 c;
    while (n > 0) {
        win_set(0, (u8)(STAGE_BLK + (off >> 13)));
        c = (u16)(0x2000u - (off & 0x1FFFu));
        if (c > n)
            c = n;
        k_copy(dst, WIN0 + (off & 0x1FFFu), (u8)c);
        dst += c;
        off += c;
        n -= c;
    }
}

/* 1 when a mounted volume holds the file `name` (Pascal string, no extension); a new disk in drive 1 is looked at too */
u16 api_FileKnown(const u8 *name)
{
    char n8[9];
    name8_of(name, n8);
    if (vol_has(n8))
        return 1;
    if (vol_mount(&vols[1], 1) == 0 && vol_has(n8))
        return 1;
    return 0;
}

/* ---- video, text, fills */

static u8 video_up;

void api_SetVideoMode(u8 mode)
{
    (void)mode;
    if (!video_up) {
        gfx_init();
        db_init();
        video_up = 1;
    } else {
        gfx_clear(0);
        gfx_default_palette();
    }
}

void api_RestoreVideoMode(void)
{
    /* the game goes back to text mode to print an error and quit: stop here and say so (development) */
    MB_RESULT(30) = 0xE7;
    MB_STATUS = MB_FAIL;
    eng_halt();
}

void api_SetPageSegment(u8 page) { (void)page; }
void api_SetActivePage(u8 page) { (void)page; }
